# DK AGH.  Almindingen - Gudhjem
#
let ag = path("d3.dk.agh");

with detail = 4, railway = :third :narrow:g1000 :pax :removed {
    # point.dk.Almindingen  dk.AKA

    with link = "line.dk.AGH" {
        track(ag[:alm + 0.49sw, :alm + 0.51km]);
        line_label(:right:w, ag[:alm + 0.5km] >> 0.5lt, "AGH");
        track(ag[:alm + 0.49km, :chr - 0.49sw]);
    }

    with link = "point.dk.Christianshøj", railway = :station {
        track(ag[:chr - 0.5sw, :chr + 0.5sw]);
        marker(:left :de.hp, ag[:chr] << 0.5lt);
        station(:top, ag[:chr] << 0.5lt << 1sh << 0.8dt,
            "Christianshøj", "AGH: 6,8"
        );
    }

    with link = "line.dk.AGH" {
        track(ag[:chr + 0.49sw, :alo - 0.49sw]);
    }

    with link = "point.dk.Aaløse", railway = :station {
        track(ag[:alo - 0.5sw, :alo + 0.5sw]);
        marker(:right :de.bf, ag[:alo] >> 0.5lt);
        station(:bottom, ag[:alo] >> 0.5lt >> 1sh + (0.9dt, 0.9dt),
            "Aaløse", "AGH: 10,7"
        );
    }

    with link = "line.dk.AGH" {
        track(ag[:alo + 0.49sw, :oma - 0.49sw]);
    }

    with link = "point.dk.Østermarie", railway = :station {
        track(ag[:oma - 0.5sw, :oma + 0.5sw]);
        marker(:right :de.bf, ag[:oma] >> 0.5lt);
        station(:right, ag[:oma] >> 0.5lt >> 1sh + (1.5dt, 1.0dt),
            "Østermarie", "AGH: 13,7"
        );
    }

    with link = "line.dk.AGH" {
        track(ag[:oma + 0.49sw, :ola - 0.49sw]);
    }

    with link = "point.dk.Østerlars", railway = :station {
        track(ag[:ola - 0.5sw, :ola + 0.5sw]);
        marker(:left :de.bf, ag[:ola] << 0.5lt);
        station(:bottom, ag[:ola] << 0.5lt << 1sh << 0.9dt,
            "Østerlars", "AGH: 17,8"
        );
    }

    with link = "line.dk.AGH" {
        track(ag[:ola + 0.49sw, :sta - 0.49sw]);
    }

    with link = "point.dk.Stavehøl", railway = :station {
        track(ag[:sta - 0.5sw, :sta + 0.5sw]);
        marker(:right :de.hp, ag[:sta] >> 0.5lt);
        station(:right, ag[:sta] >> 0.5lt >> 1sh + (1.5dt, 1.0dt),
            "Stavehøl", "AGH: 20,5"
        );
    }

    with link = "line.dk.AGH" {
        track(ag[:sta + 0.49sw, :gud - 0.49sw]);
    }

    with link = "point.dk.Gudhjem", railway = :station {
        track(ag[:gud - 0.5sw, :gud + 0.5sw]);
        marker(:left :de.bf, ag[:gud] << 0.5lt);
        station(:left, ag[:gud] << 0.5lt << 1sh + (-2.0dt, 1.0dt),
            span(:bold, "Gudhjem"), "AGH: 23,1"
        );
    }
}

